<script setup>
import {reactive,ref,computed,watch,nextTick} from 'vue';
const props=defineProps({encoding:Object}),e=reactive(props.encoding),root=ref(null),visible=computed(()=>!!e.recovery);let previous;
watch(visible,async show=>{if(show){previous=document.activeElement;await nextTick();root.value?.querySelector('button')?.focus();}else previous?.focus?.();});
function keyboard(event){event.stopPropagation();if(event.key==='Escape'){event.preventDefault();return;}if(event.key!=='Tab')return;const controls=[...root.value.querySelectorAll('button,a[href]')].filter(el=>!el.disabled),first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
</script>
<template><Teleport to="body"><div v-if="e.recovery" class="modal-backdrop encoding-recovery" @keydown="keyboard" @pointerdown.stop><section ref="root" class="export-dialog" role="dialog" aria-modal="true" aria-label="Capture vidéo conservée"><h2>Ta capture est conservée.</h2><p role="alert">{{e.recovery.error}}</p><p class="field-help">Tu peux relancer l’encodage ou télécharger la capture source MOV PNG pour la récupérer. Elle reste disponible tant que cette fenêtre est ouverte.</p><div class="encoding-actions"><button class="btn primary" :disabled="e.busy" @click="e.retry">{{e.busy?'Encodage…':'Réessayer l’encodage'}}</button><a class="btn" :href="e.recovery.url" :download="e.recovery.sourceName">Télécharger la capture source</a><button class="btn" :disabled="e.busy" @click="e.discard">Fermer et libérer la capture</button></div></section></div></Teleport></template>
<style scoped>.encoding-recovery{z-index:1100}.encoding-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}</style>
